BEGIN;
CREATE SEQUENCE IF NOT EXISTS commercial_seq START 1;CREATE SEQUENCE IF NOT EXISTS receivable_seq START 1;CREATE SEQUENCE IF NOT EXISTS payable_seq START 1;CREATE SEQUENCE IF NOT EXISTS expense_seq START 1;
ALTER TABLE buyers ADD COLUMN IF NOT EXISTS credit_limit NUMERIC(16,2) DEFAULT 0;ALTER TABLE buyers ADD COLUMN IF NOT EXISTS internal_credit_rating TEXT;ALTER TABLE buyers ADD COLUMN IF NOT EXISTS bad_debt_history TEXT;
CREATE TABLE finance_cost_centres(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,is_active BOOLEAN DEFAULT TRUE);INSERT INTO finance_cost_centres(name)VALUES('Sales'),('Logistics'),('Marketing'),('Administration'),('Business Development'),('Corporate')ON CONFLICT DO NOTHING;
CREATE TABLE finance_ageing_buckets(id BIGSERIAL PRIMARY KEY,label TEXT NOT NULL,min_days INTEGER NOT NULL,max_days INTEGER,color TEXT NOT NULL,sort_order INTEGER DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);INSERT INTO finance_ageing_buckets(label,min_days,max_days,color,sort_order)VALUES('1–7 Days',1,7,'green',1),('8–15 Days',8,15,'green',2),('16–24 Days',16,24,'yellow',3),('25–31 Days',25,31,'yellow',4),('32–60 Days',32,60,'orange',5),('61–90 Days',61,90,'orange',6),('91–180 Days',91,180,'red',7),('Above 180 Days',181,NULL,'red',8)ON CONFLICT DO NOTHING;
CREATE TABLE finance_commercial_records(id BIGSERIAL PRIMARY KEY,commercial_number TEXT NOT NULL UNIQUE DEFAULT('COM-'||to_char(CURRENT_DATE,'YYYY')||'-'||lpad(nextval('commercial_seq')::text,6,'0')),order_id BIGINT NOT NULL UNIQUE REFERENCES orders(id) ON DELETE RESTRICT,transaction_id BIGINT REFERENCES sales_transactions(id) ON DELETE RESTRICT,supplier_invoice_number TEXT,supplier_invoice_date DATE,supplier_invoice_value NUMERIC(16,2) DEFAULT 0,buyer_invoice_number TEXT,buyer_invoice_date DATE,buyer_invoice_value NUMERIC(16,2) DEFAULT 0,credit_cost NUMERIC(16,2) DEFAULT 0,interest_cost NUMERIC(16,2) DEFAULT 0,miscellaneous_cost NUMERIC(16,2) DEFAULT 0,commercial_status TEXT DEFAULT 'Open',collection_owner INTEGER REFERENCES users(id) ON DELETE SET NULL,collection_remarks TEXT,remarks TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,last_modified_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now(),updated_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_receivable_invoices(id BIGSERIAL PRIMARY KEY,invoice_number TEXT NOT NULL UNIQUE DEFAULT('REC-'||lpad(nextval('receivable_seq')::text,7,'0')),commercial_id BIGINT NOT NULL REFERENCES finance_commercial_records(id) ON DELETE RESTRICT,buyer_id BIGINT NOT NULL REFERENCES buyers(id) ON DELETE RESTRICT,invoice_date DATE NOT NULL,invoice_value NUMERIC(16,2) NOT NULL CHECK(invoice_value>=0),payment_terms TEXT,credit_days INTEGER DEFAULT 0,due_date DATE NOT NULL,reminder_status TEXT DEFAULT 'Not Sent',collection_owner INTEGER REFERENCES users(id) ON DELETE SET NULL,collection_remarks TEXT,status TEXT DEFAULT 'Outstanding',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_payable_invoices(id BIGSERIAL PRIMARY KEY,invoice_number TEXT NOT NULL UNIQUE DEFAULT('PAY-'||lpad(nextval('payable_seq')::text,7,'0')),supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT,supplier_invoice_number TEXT,invoice_date DATE NOT NULL,purchase_value NUMERIC(16,2) NOT NULL CHECK(purchase_value>=0),payment_terms TEXT,credit_days INTEGER DEFAULT 0,due_date DATE NOT NULL,status TEXT DEFAULT 'Outstanding',created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_payable_order_links(payable_id BIGINT NOT NULL REFERENCES finance_payable_invoices(id) ON DELETE RESTRICT,order_id BIGINT NOT NULL REFERENCES orders(id) ON DELETE RESTRICT,allocated_value NUMERIC(16,2) NOT NULL CHECK(allocated_value>=0),PRIMARY KEY(payable_id,order_id));
CREATE TABLE finance_customer_payments(id BIGSERIAL PRIMARY KEY,payment_reference TEXT NOT NULL UNIQUE,buyer_id BIGINT NOT NULL REFERENCES buyers(id) ON DELETE RESTRICT,payment_date DATE NOT NULL DEFAULT CURRENT_DATE,amount NUMERIC(16,2) NOT NULL CHECK(amount>0),payment_mode TEXT,bank_reference TEXT,remarks TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_receipt_allocations(payment_id BIGINT NOT NULL REFERENCES finance_customer_payments(id) ON DELETE RESTRICT,receivable_id BIGINT NOT NULL REFERENCES finance_receivable_invoices(id) ON DELETE RESTRICT,allocated_amount NUMERIC(16,2) NOT NULL CHECK(allocated_amount>0),PRIMARY KEY(payment_id,receivable_id));
CREATE TABLE finance_supplier_payments(id BIGSERIAL PRIMARY KEY,payment_reference TEXT NOT NULL UNIQUE,supplier_id BIGINT NOT NULL REFERENCES suppliers(id) ON DELETE RESTRICT,payment_date DATE DEFAULT CURRENT_DATE,amount NUMERIC(16,2) NOT NULL CHECK(amount>0),payment_mode TEXT,bank_reference TEXT,remarks TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_payment_allocations(payment_id BIGINT NOT NULL REFERENCES finance_supplier_payments(id) ON DELETE RESTRICT,payable_id BIGINT NOT NULL REFERENCES finance_payable_invoices(id) ON DELETE RESTRICT,allocated_amount NUMERIC(16,2) NOT NULL CHECK(allocated_amount>0),PRIMARY KEY(payment_id,payable_id));
CREATE TABLE finance_expenses(id BIGSERIAL PRIMARY KEY,expense_number TEXT NOT NULL UNIQUE DEFAULT('EXP-'||lpad(nextval('expense_seq')::text,7,'0')),expense_date DATE NOT NULL DEFAULT CURRENT_DATE,category TEXT NOT NULL,cost_centre_id BIGINT REFERENCES finance_cost_centres(id) ON DELETE SET NULL,vendor TEXT,amount NUMERIC(16,2) NOT NULL CHECK(amount>=0),payment_status TEXT DEFAULT 'Pending',approval_status TEXT DEFAULT 'Pending',remarks TEXT,attachment_url TEXT,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_documents(id BIGSERIAL PRIMARY KEY,commercial_id BIGINT REFERENCES finance_commercial_records(id) ON DELETE RESTRICT,document_type TEXT NOT NULL,file_name TEXT NOT NULL,file_url TEXT NOT NULL,version_number INTEGER DEFAULT 1,uploaded_by INTEGER REFERENCES users(id) ON DELETE SET NULL,created_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_timeline(id BIGSERIAL PRIMARY KEY,commercial_id BIGINT NOT NULL REFERENCES finance_commercial_records(id) ON DELETE RESTRICT,event_type TEXT NOT NULL,description TEXT NOT NULL,created_by INTEGER REFERENCES users(id) ON DELETE SET NULL,occurred_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_approval_rules(id BIGSERIAL PRIMARY KEY,approval_type TEXT NOT NULL,threshold_amount NUMERIC(16,2),threshold_percent NUMERIC(8,2),approver_role_id INTEGER REFERENCES roles(id) ON DELETE SET NULL,is_active BOOLEAN DEFAULT TRUE);CREATE TABLE finance_approval_requests(id BIGSERIAL PRIMARY KEY,rule_id BIGINT REFERENCES finance_approval_rules(id),commercial_id BIGINT REFERENCES finance_commercial_records(id),expense_id BIGINT REFERENCES finance_expenses(id),reason TEXT,status TEXT DEFAULT 'Pending',requested_by INTEGER REFERENCES users(id),approved_by INTEGER REFERENCES users(id),requested_at TIMESTAMPTZ DEFAULT now(),decided_at TIMESTAMPTZ,remarks TEXT);
CREATE TABLE finance_audit_log(id BIGSERIAL PRIMARY KEY,entity_type TEXT NOT NULL,entity_id BIGINT NOT NULL,action TEXT NOT NULL,old_values JSONB,new_values JSONB,user_id INTEGER REFERENCES users(id) ON DELETE SET NULL,occurred_at TIMESTAMPTZ DEFAULT now());
CREATE TABLE finance_cash_accounts(id BIGSERIAL PRIMARY KEY,name TEXT NOT NULL UNIQUE,opening_balance NUMERIC(16,2) DEFAULT 0,is_active BOOLEAN DEFAULT TRUE);INSERT INTO finance_cash_accounts(name,opening_balance)VALUES('Primary Cash Account',0)ON CONFLICT DO NOTHING;
CREATE OR REPLACE VIEW finance_receivables_view AS SELECT r.*,b.group_name buyer,COALESCE(sum(a.allocated_amount),0)amount_received,GREATEST(r.invoice_value-COALESCE(sum(a.allocated_amount),0),0)outstanding,GREATEST(CURRENT_DATE-r.due_date,0)days_outstanding,COALESCE((SELECT label FROM finance_ageing_buckets x WHERE x.is_active AND GREATEST(CURRENT_DATE-r.due_date,0)>=x.min_days AND(x.max_days IS NULL OR GREATEST(CURRENT_DATE-r.due_date,0)<=x.max_days)ORDER BY x.sort_order LIMIT 1),'Not Due')ageing_bucket,COALESCE((SELECT color FROM finance_ageing_buckets x WHERE x.is_active AND GREATEST(CURRENT_DATE-r.due_date,0)>=x.min_days AND(x.max_days IS NULL OR GREATEST(CURRENT_DATE-r.due_date,0)<=x.max_days)ORDER BY x.sort_order LIMIT 1),'green')ageing_color FROM finance_receivable_invoices r JOIN buyers b ON b.id=r.buyer_id LEFT JOIN finance_receipt_allocations a ON a.receivable_id=r.id GROUP BY r.id,b.group_name;
CREATE OR REPLACE VIEW finance_payables_view AS SELECT p.*,s.group_name supplier,COALESCE(sum(a.allocated_amount),0)amount_paid,GREATEST(p.purchase_value-COALESCE(sum(a.allocated_amount),0),0)outstanding,GREATEST(CURRENT_DATE-p.due_date,0)days_outstanding FROM finance_payable_invoices p JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN finance_payment_allocations a ON a.payable_id=p.id GROUP BY p.id,s.group_name;
CREATE OR REPLACE VIEW finance_commercial_register_view AS SELECT c.id,c.commercial_number,o.inquiry_number,o.order_number,b.group_name buyer_name,s.group_name supplier_name,u.name sales_representative,o.order_date,o.dispatch_date,o.delivery_date,c.commercial_status,b.pan buyer_gst,b.state,o.place_of_supply,o.payment_terms,0 credit_days,o.product_category,o.grade,o.quantity_kg,'Kg' unit,NULL::text hsn_code,c.supplier_invoice_number,c.supplier_invoice_date,c.supplier_invoice_value,o.purchase_price_per_kg purchase_price,o.quantity_kg*COALESCE(o.purchase_price_per_kg,0)total_purchase_value,c.buyer_invoice_number,c.buyer_invoice_date,COALESCE(c.buyer_invoice_value,o.total_order_value)buyer_invoice_value,o.sale_price_per_kg selling_price,o.total_order_value total_revenue,COALESCE(lc.freight_cost,0)freight_cost,COALESCE(lc.door_delivery_charges,0)door_delivery_charges,COALESCE(lc.porter_charges,0)porter_charges,COALESCE(lc.other_charges,0)other_logistics_charges,COALESCE(lc.total_logistics_cost,o.quantity_kg*COALESCE(o.freight_per_kg,0))total_logistics_cost,o.freight_per_kg,COALESCE(c.buyer_invoice_value,o.total_order_value)gross_revenue,(o.quantity_kg*COALESCE(o.purchase_price_per_kg,0))cogs,(COALESCE(c.buyer_invoice_value,o.total_order_value)-o.quantity_kg*COALESCE(o.purchase_price_per_kg,0)-COALESCE(lc.total_logistics_cost,o.quantity_kg*COALESCE(o.freight_per_kg,0)))gross_profit,round((100*(COALESCE(c.buyer_invoice_value,o.total_order_value)-o.quantity_kg*COALESCE(o.purchase_price_per_kg,0)-COALESCE(lc.total_logistics_cost,o.quantity_kg*COALESCE(o.freight_per_kg,0)))/NULLIF(COALESCE(c.buyer_invoice_value,o.total_order_value),0))::numeric,2)gross_margin_percent,c.credit_cost,c.interest_cost,c.miscellaneous_cost,(COALESCE(c.buyer_invoice_value,o.total_order_value)-o.quantity_kg*COALESCE(o.purchase_price_per_kg,0)-COALESCE(lc.total_logistics_cost,o.quantity_kg*COALESCE(o.freight_per_kg,0))-c.credit_cost-c.interest_cost-c.miscellaneous_cost)net_profit,round((100*(COALESCE(c.buyer_invoice_value,o.total_order_value)-o.quantity_kg*COALESCE(o.purchase_price_per_kg,0)-COALESCE(lc.total_logistics_cost,o.quantity_kg*COALESCE(o.freight_per_kg,0))-c.credit_cost-c.interest_cost-c.miscellaneous_cost)/NULLIF(COALESCE(c.buyer_invoice_value,o.total_order_value),0))::numeric,2)net_margin_percent,rv.due_date,COALESCE(rv.amount_received,0)amount_received,COALESCE(rv.outstanding,COALESCE(c.buyer_invoice_value,o.total_order_value))outstanding_amount,COALESCE(rv.days_outstanding,0)days_outstanding,COALESCE(rv.status,'Not Invoiced')collection_status,c.created_at,c.updated_at,o.status current_stage,c.remarks FROM finance_commercial_records c JOIN orders o ON o.id=c.order_id JOIN buyers b ON b.id=o.buyer_id LEFT JOIN suppliers s ON s.id=o.supplier_id LEFT JOIN sales_transactions t ON t.id=c.transaction_id LEFT JOIN users u ON u.id=t.sales_representative LEFT JOIN logistics_cost_register lc ON lc.order_reference=o.order_number LEFT JOIN finance_receivables_view rv ON rv.commercial_id=c.id;
CREATE OR REPLACE FUNCTION finance_sync_order()RETURNS trigger LANGUAGE plpgsql AS $$DECLARE cid BIGINT;BEGIN IF NEW.status IN('Order Confirmed','Supplier Ordered','Dispatch Planned','Invoice Generated','Dispatched','Delivered','Completed','Closed')THEN INSERT INTO finance_commercial_records(order_id,transaction_id,buyer_invoice_number,buyer_invoice_date,buyer_invoice_value,commercial_status)VALUES(NEW.id,NEW.transaction_id,NEW.invoice_number,NEW.invoice_date,COALESCE(NEW.invoice_value,NEW.total_order_value),NEW.status)ON CONFLICT(order_id)DO UPDATE SET buyer_invoice_number=EXCLUDED.buyer_invoice_number,buyer_invoice_date=EXCLUDED.buyer_invoice_date,buyer_invoice_value=EXCLUDED.buyer_invoice_value,commercial_status=EXCLUDED.commercial_status,updated_at=now()RETURNING id INTO cid;INSERT INTO finance_timeline(commercial_id,event_type,description)VALUES(cid,'Order Sync','Commercial record synchronized from order');END IF;RETURN NEW;END$$;DROP TRIGGER IF EXISTS trg_finance_sync_order ON orders;CREATE TRIGGER trg_finance_sync_order AFTER INSERT OR UPDATE OF status,invoice_number,invoice_value ON orders FOR EACH ROW EXECUTE FUNCTION finance_sync_order();
INSERT INTO finance_commercial_records(order_id,transaction_id,buyer_invoice_number,buyer_invoice_date,buyer_invoice_value,commercial_status)SELECT id,transaction_id,invoice_number,invoice_date,COALESCE(invoice_value,total_order_value),status FROM orders WHERE deleted_at IS NULL AND status IN('Order Confirmed','Supplier Ordered','Dispatch Planned','Invoice Generated','Dispatched','Delivered','Completed','Closed')ON CONFLICT(order_id)DO NOTHING;
DROP TABLE IF EXISTS finance;
CREATE INDEX idx_finance_commercial_order ON finance_commercial_records(order_id);CREATE INDEX idx_finance_receivable_due ON finance_receivable_invoices(due_date,status);CREATE INDEX idx_finance_payable_due ON finance_payable_invoices(due_date,status);CREATE INDEX idx_finance_expense_date ON finance_expenses(expense_date,category);CREATE INDEX idx_finance_audit_entity ON finance_audit_log(entity_type,entity_id,occurred_at DESC);
UPDATE roles SET permissions=jsonb_set(COALESCE(permissions,'{}'::jsonb),'{modules,finance}','true'::jsonb,true);
COMMIT;
